begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(25);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp181@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18100000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18100000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000004','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000005','18100000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18100000-0000-0000-0000-000000000006','18100000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18100000-0000-0000-0000-000000000007','18100000-0000-0000-0000-000000000002','Synthetic staff');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18100000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-recipient@example.invalid','x',now(),now());
insert into public.organization_members(organization_id,user_id,role) values ('18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000009','member');
update public.staffs set user_id='18100000-0000-0000-0000-000000000009' where id='18100000-0000-0000-0000-000000000007';

insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18100000-0000-0000-0000-000000000008','18100000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_update_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18100000-0000-0000-0000-000000000002',true,'{}','18100000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp180-browser','mcp180-browser','18100000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
set constraints all immediate;
set constraints all deferred;
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
select is(public.get_mcp_master_edit_control('18100000-0000-0000-0000-000000000002')->>'enabled','false','master edit is disabled by default');
select throws_ok($$select public.enable_mcp_master_edit('18100000-0000-0000-0000-000000000002','{}')$$,'22023','invalid_mcp_conditions','enable requires processing conditions');
select public.enable_mcp_master_edit('18100000-0000-0000-0000-000000000002','{"provider":"test","processing":"test","region":"test","retention":"test","secondary_use":"test","notice":"test"}');
select is(public.get_mcp_master_edit_control('18100000-0000-0000-0000-000000000002')->>'enabled','true','administrator can enable');
select is((select count(*) from public.audit_events where action_type='integration.mcp_master_edit.enable'),1::bigint,'enable is audited');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
select set_config('test.client',private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','client','18100000-0000-0000-0000-000000000006','{"name":"Renamed client"}')::text,true);
select set_config('test.staff',private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','staff','18100000-0000-0000-0000-000000000007','{"name":"Renamed staff","employment_type":"常勤","work_style":"専従"}')::text,true);
select set_config('test.stale',private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','client','18100000-0000-0000-0000-000000000006','{"name":"Stale client"}')::text,true);
select is(public.get_mcp_master_edit_result('18100000-0000-0000-0000-000000000002',current_setting('test.client')::uuid)->>'status','confirmation_required','MCP can poll its own pending proposal');
select ok(not has_function_privilege('mcp_import','public.confirm_mcp_master_edit(uuid)','execute'),'MCP cannot confirm an edit');
select is((select name from public.clients where id='18100000-0000-0000-0000-000000000006'),'Synthetic client','preparation does not change client');
select throws_ok($$select public.confirm_mcp_master_edit(current_setting('test.client')::uuid)$$,'42501','proposal_unavailable','OAuth cannot confirm');
select throws_ok($$select private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','staff','18100000-0000-0000-0000-000000000007','{"user_id":"18100000-0000-0000-0000-000000000001"}')$$,'22023','invalid_master_proposal','account linkage cannot be edited');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18100000-0000-0000-0000-000000000030','18100000-0000-0000-0000-000000000009','18100000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18100000-0000-0000-0000-000000000030';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18100000-0000-0000-0000-000000000031','18100000-0000-0000-0000-000000000009','18100000-0000-0000-0000-000000000003',now());
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000009","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000031"}',true);
select throws_ok($$select private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','client','18100000-0000-0000-0000-000000000006','{"name":"Unauthorized"}')$$,'42501','proposal_unavailable','member without client management is rejected');
select throws_ok($$select private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000099','staff','18100000-0000-0000-0000-000000000007','{"name":"Wrong org"}')$$,'42501','proposal_unavailable','other organization is rejected');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
select is(public.get_mcp_master_edit_review(current_setting('test.client')::uuid)->'proposal'->>'name','Renamed client','browser review displays fixed proposed name');
select is(public.confirm_mcp_master_edit(current_setting('test.client')::uuid)->>'status','updated','browser confirms client update');
select is((select name from public.clients where id='18100000-0000-0000-0000-000000000006'),'Renamed client','client name updated');
select is((select count(*) from public.audit_events where action_type='client.rename' and resource_id='18100000-0000-0000-0000-000000000006'),1::bigint,'client rename audited');
select is(public.confirm_mcp_master_edit(current_setting('test.staff')::uuid)->>'status','updated','browser confirms staff update');
select is((select employment_type from public.staffs where id='18100000-0000-0000-0000-000000000007'),'常勤','staff employment type updated');
select is((select count(*) from public.audit_events where action_type='staff.update' and resource_id='18100000-0000-0000-0000-000000000007'),1::bigint,'staff update audited');
select is(public.confirm_mcp_master_edit(current_setting('test.staff')::uuid)->>'newly_updated','false','repeated confirmation does not update twice');
select throws_ok($$select public.confirm_mcp_master_edit(current_setting('test.stale')::uuid)$$,'22023','proposal_changed','changed name rejects stale proposal');
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18100000-0000-0000-0000-000000000003","session_id":"18100000-0000-0000-0000-000000000005"}',true);
select set_config('test.audit',private.prepare_mcp_master_edit('18100000-0000-0000-0000-000000000002','client','18100000-0000-0000-0000-000000000006','{"name":"Must roll back"}')::text,true);
select set_config('request.jwt.claims','{"sub":"18100000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp180-browser"}',true);
savepoint audit_failure;
create function pg_temp.reject_master_audit() returns trigger language plpgsql as $$begin raise exception 'synthetic audit failure'; end$$;
create trigger synthetic_master_audit_failure before insert on public.audit_events for each row execute function pg_temp.reject_master_audit();
select throws_ok($$select public.confirm_mcp_master_edit(current_setting('test.audit')::uuid)$$,'P0001','synthetic audit failure','audit failure rejects edit');
select is((select name from public.clients where id='18100000-0000-0000-0000-000000000006'),'Renamed client','audit failure rolls back edit');
select is((select confirmed_at from private.mcp_master_edit_proposals where id=current_setting('test.audit')::uuid),null::timestamptz,'audit failure does not consume proposal');
rollback to savepoint audit_failure;
update private.mcp_master_edit_controls set enabled=false where organization_id='18100000-0000-0000-0000-000000000002';
select throws_ok($$select public.confirm_mcp_master_edit(current_setting('test.stale')::uuid)$$,'42501','proposal_unavailable','disabled control rejects confirmation');
update private.mcp_master_edit_controls set enabled=true where organization_id='18100000-0000-0000-0000-000000000002';
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18100000-0000-0000-0000-000000000004';
select throws_ok($$select public.confirm_mcp_master_edit(current_setting('test.stale')::uuid)$$,'42501','proposal_unavailable','revoked connection rejects confirmation');
select * from finish();
rollback;
